async function n(){return fetch("https://plant-web-service.onrender.com/api/plants").then(e=>{if(!e.ok)throw new Error("Network response was not ok");return e.json()}).then(e=>(console.log(e),e)).catch(e=>{console.error("There was a problem with the fetch operation:",e)})}let o=n(),t=document.createElement("span");t.innerHTML=o;let r=document.querySelector("body");r.appendChild(t);
